const context = $('Filter Candidates').first().json;
const language = context.language;
const count = context.count;

const normalizeWord = (word) => String(word)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Za-z]/g, '')
  .toUpperCase();

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
if (!text) {
  throw new Error('Gemini no devolvio texto de validacion. Revisa la credencial Header Auth, la API key, el modelo o la respuesta del nodo HTTP.');
}

let parsed;
try {
  const cleanedText = text.trim().replace(/^```json\s*/i, '').replace(/^```/i, '').replace(/```$/i, '').trim();
  parsed = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(`Gemini no respondio JSON valido: ${text}`);
}

if (!Array.isArray(parsed.words)) {
  throw new Error('Gemini no devolvio el arreglo words.');
}

const finalWords = [];
const seen = new Set();
for (const word of parsed.words) {
  const cleaned = normalizeWord(word);
  if (!cleaned) continue;
  if (seen.has(cleaned)) continue;
  seen.add(cleaned);
  finalWords.push(cleaned);
}

if (finalWords.length !== count) {
  throw new Error(`Gemini debe validar exactamente ${count} palabras; devolvio ${finalWords.length}.`);
}

return [{
  json: {
    language,
    words: finalWords
  }
}];
